const key=new URLSearchParams(location.search).get('scheme')||'a';const groups={a:['01 视频配色：纯色 / 渐变',[['solid','提色纯色','暗蓝灰取自示例帧；记录栏同色纯底'],['tinted','提色渐变','蓝灰与火焰暖棕低饱和混合；记录栏纯色']]],b:['02 渐隐悬浮 / 当前帧背景',[['fade','黑色到透明','轮盘和输入浮层向外渐隐；记录栏保持实体'],['still','当前帧作背景','以静止示例帧叠暗色透明层；记录栏保持纯色']]],c:['03 自定义背景 / 视频帧背景对照',[['custom','自定义背景方向','以原创冷色背景示意；本轮没有读取用户文件'],['still','视频帧背景方向','使用同一布局对比材质，避免颜色变化干扰判断']]]};const paths={up:'<path d="m5 17 1-4L16 3l4 4L10 17zM4 21h16"/>',left:'<path d="M8 4H4v16h4m8-16h4v16h-4M9 12h6"/>',down:'<rect x="4" y="6" width="16" height="14"/><path d="M7 3h10m-13 12 5-5 5 5 3-3 3 3"/>',right:'<path d="M19 8a8 8 0 0 0-13-2L3 9m0-5v5h5m-3 7a8 8 0 0 0 13 2l3-3m0 5v-5h-5"/>'};const wheel=Object.entries({up:'标注',left:'片段',down:'记录',right:'循环'}).map(([p,t])=>'<span class="item '+p+'"><svg viewBox="0 0 24 24">'+paths[p]+'</svg>'+t+'</span>').join('');const g=groups[key];document.getElementById('board').innerHTML='<header><h1>'+g[0]+'</h1><p>A 的结构保持一致，放大观察弹出材质与图标轮盘。</p></header><div class="grid">'+g[1].map(([cl,title,sub])=>'<section class="sample '+cl+'"><div class="bar"><span>炎舞连斩</span><span>—　□　×</span></div><div class="scene"></div><div class="wheel">'+wheel+'<span class="center"></span></div><aside class="record">记录<img src="../design-round-02/assets/scene-1.svg"><img src="../design-round-02/assets/scene-2.svg"></aside><div class="editor">火焰边缘散开，主体轮廓开始消失。<small>Enter 保存　Shift + Enter 换行</small></div><div class="timeline"></div><div class="caption">'+title+'<small>'+sub+'</small></div></section>').join('')+'</div><p class="detail-note">上方是材质对照板：为便于比较，轮盘与输入框同时展开；不代表正式操作时同时常驻。<br>本轮配色为从合成画面人工选取的实验色，未实现真实视频自动提色。自定义背景是效果示意，尚未接入图片选择。<br>记录栏在全部方案中保持纯色。下方保留 A 的整体比例参照。</p><iframe src="a.html?state=records" style="width:1600px;height:860px;border:0;transform:scale(.59);transform-origin:top left;margin-top:10px"></iframe>';window.DESIGN_READY=new Promise(r=>document.querySelector('iframe').addEventListener('load',r,{once:true}));